"""Property tests: malformed testbench.yaml, rules, reports, run folders, price catalogs and notebooks, generated by the
thousand. A bad input gets a ConfigError (or a failing check), never a traceback, and no check passes that should fail.
Derandomized with no example database, so CI sees the same examples every time; the examples each bug needed are
plain tests in test_bad_inputs.py."""
import copy
import json
import math
import os
import tempfile
import time
import xml.etree.ElementTree as ET
from fractions import Fraction
from pathlib import Path

import nbformat
import pytest
import yaml

pytest.importorskip("hypothesis")
from hypothesis import HealthCheck, assume, given, settings, strategies as st  # noqa: E402

from agent_testbench import budget, config as C, expect, loop as LP, notebook as NB, prices, provenance  # noqa: E402
from agent_testbench import report as R, scaffold, ui  # noqa: E402
from agent_testbench.backends import colab_backend, modal_backend  # noqa: E402


def fast(n: int):
    """n examples, the same every run (TESTBENCH_FUZZ_SCALE=20 looks twenty times as hard, for a session of bug hunting).
    Dictionaries drawn from sets differ with PYTHONHASHSEED, so an unseen seed can still find something real."""
    n *= int(os.environ.get("TESTBENCH_FUZZ_SCALE", "1"))
    return settings(max_examples=n, derandomize=True, database=None, deadline=None,
                    suppress_health_check=[HealthCheck.function_scoped_fixture, HealthCheck.too_slow])


ODD = ["", "\ud800", "\udce9", "\x1b[31m", "\x00", "|", "\n# PASS", "<script>", "nan", "inf", "-1", ": x", "&amp;"]
odd_text = st.builds(lambda a, b: a + b, st.text(max_size=10), st.sampled_from(ODD))
scalars = st.one_of(st.none(), st.booleans(), st.integers(), st.floats(), st.text(max_size=8), st.sampled_from(ODD))
values = st.recursive(scalars, lambda inner: st.lists(inner, max_size=3)
                      | st.dictionaries(st.one_of(st.text(max_size=6), st.integers()), inner, max_size=3), max_leaves=6)

# ---- testbench.yaml ----------------------------------------------------------------------------------------------

ROOT = Path(tempfile.mkdtemp(prefix="testbench-fuzz-"))
nbformat.write(nbformat.v4.new_notebook(cells=[nbformat.v4.new_code_cell("N = 1 #@param")]), str(ROOT / "nb.ipynb"))
(ROOT / "m.json").write_text('{"acc": 0.95, "l": [0.3, 0.2]}')
(ROOT / "log.txt").write_text("done\n")
(ROOT / "r.xml").write_text('<testsuite tests="1"><testcase name="a"/></testsuite>')
BASE = {"project": "p",
        "budget": {"max_run_usd": 2.0, "ask_above_usd": 0.5, "max_day_usd": 10.0},
        "sessions": {"backend": "local", "idle_minutes": 10, "max_minutes": 60, "secrets": []},
        "pricing": {"modal_gpu_per_s": {"T4": 0.0002}, "modal_cpu_core_per_s": 0.00002},
        "modal": {"cpu": 2.0, "memory_gb": 8, "pip": ["numpy"]}, "exclude": [".git"], "guard": {"ask": ["git push"]},
        "plans": {"p": {"backend": "modal", "gpu": "T4", "steps": [
            {"name": "nb", "notebook": "nb.ipynb", "max_minutes": 5, "params": {"N": 1}, "cells": "1", "uploads": [["a"]]},
            {"name": "run", "run": "true", "max_minutes": 1, "env": {"A": "1"}, "artifacts": ["out/*"], "secrets": ["K"],
             "expect": {"exit_code": 0, "files": ["out/a"], "json": {"m.json": {"acc": ">= 0.9", "l.-1": "~= 0.2 +- 0.1"}},
                        "text": {"stdout": ["hi"], "log.txt": "done"}, "media": {"v.mp4": {"frames": ">= 1"}},
                        "junit": {"path": "r.xml", "tests": ">= 1"}, "metrics": {"stdout": {"loss=([0-9.]+)": "< 1"}},
                        "gpu": {"busy_pct": ">= 1"}, "image": {"a.png": {"like": "g.png", "max_diff": 0.1}},
                        "duration": {"minutes": "<= 5"}}},
            {"name": "web", "web": {"url": "http://127.0.0.1:9/", "actions": [], "viewport": [10, 10]},
             "expect": {"web": {"status": "between 200 and 299", "text": ["x"], "title": "t"}}}]},
            "q": {"backend": "local", "steps": [{"name": "a", "run": "x", "max_minutes": 2}]}}}


def _paths(node, at=()):
    yield at
    items = node.items() if isinstance(node, dict) else enumerate(node) if isinstance(node, list) else ()
    for k, v in items:
        yield from _paths(v, at + (k,))


PATHS = [p for p in _paths(BASE) if p]


def _set(raw, path, value, delete=False):
    for k in path[:-1]:
        raw = raw[k]
    if delete and isinstance(raw, dict):
        del raw[path[-1]]
    else:
        raw[path[-1]] = value


def _strings(x):
    if isinstance(x, str):
        yield x
    for v in (x.values() if isinstance(x, dict) else x if isinstance(x, list) else ()):
        yield from _strings(v)
    for k in (x if isinstance(x, dict) else ()):
        yield from _strings(k)


@fast(400)
@given(st.lists(st.tuples(st.sampled_from(PATHS), values, st.booleans()), min_size=1, max_size=3))
def test_any_mangled_config_is_a_config_error_or_a_config_that_holds(changes):
    raw = copy.deepcopy(BASE)
    for path, value, delete in changes:
        try:
            _set(raw, path, value, delete)
        except (KeyError, IndexError, TypeError):
            pass                                         # an earlier change removed the parent
    try:
        cfg = C.validate(raw, ROOT)
    except C.ConfigError:
        return
    for name, plan in cfg["plans"].items():              # what was accepted is priced, bounded and checkable
        ok, _, est = budget.check_launch(cfg, name, approve=True)
        assert not ok or (math.isfinite(est["worst_case_usd"]) and est["worst_case_usd"] >= 0), est
        for s in plan["steps"]:
            assert isinstance(s["name"], str) and math.isfinite(s["max_minutes"]) and s["max_minutes"] > 0
            if any(t.startswith(("/", "~")) or ".." in t for t in _strings(s["expect"])):
                continue                                 # a glob outside the project would walk this machine
            result = {"kind": s["kind"], "exit_code": 0, "stdout": "loss=0.5\nhi", "seconds": 3.0,
                      "run_started": time.time() - 60, "web": {"status": 200, "text": "x", "title": "t"},
                      "gpu": {"busy_pct": 50, "readings": 2}}
            for c in expect.check(s["expect"], workdir=ROOT, result=result):
                assert isinstance(c["ok"], bool) and isinstance(c["detail"], str)


def joined(pieces: list, most: int):
    return st.lists(st.sampled_from(pieces), min_size=1, max_size=most).map("".join)


@fast(300)
@given(joined(list("abp:-[]{}#&*!|>'\"%@`,? \n\t.0123456789<~") + ["project: p\n", "plans:\n  ", "\n  - ", "*a", "&a ",
                                                                  "<<: ", "steps:", "name: ", "run: ", ".nan", "!!set "], 40))
def test_any_yaml_text_is_a_config_error_or_a_config(text):
    with tempfile.TemporaryDirectory() as d:
        (Path(d) / "testbench.yaml").write_text(text)
        try:
            C.load(d)
        except C.ConfigError:
            pass


# ---- rules ------------------------------------------------------------------------------------------------------

nums = st.one_of(st.integers(-10 ** 6, 10 ** 6), st.floats(), st.sampled_from(["nan", "inf", "-inf", "1e999", "1_0", "x"]))
fmt = lambda x: x if isinstance(x, str) else repr(x)
rules = st.one_of(
    st.builds(lambda o, x: f"{o} {fmt(x)}", st.sampled_from([">=", "<=", "==", "!=", ">", "<", "=>", "=", "≥", ""]), nums),
    st.builds(lambda c, t, p: f"~= {fmt(c)} +- {fmt(t)}{'%' if p else ''}", nums, nums, st.booleans()),
    st.builds(lambda a, b: f"between {fmt(a)} and {fmt(b)}", nums, nums), scalars)


@fast(600)
@given(st.one_of(values, nums), rules)
def test_compare_never_raises_and_errors_never_pass(actual, rule):
    ok, detail = expect.compare(actual, rule)
    assert isinstance(ok, bool) and isinstance(detail, str)
    if expect.rule_error(rule):
        assert not ok


@fast(300)
@given(st.sampled_from([math.nan, math.inf, -math.inf]), rules,
       st.sampled_from(["nan", "inf", "-Infinity"]), st.sampled_from([">=", "<=", "==", "!=", ">", "<"]), st.floats(-9, 9))
def test_nan_and_inf_satisfy_no_rule(actual, rule, text, op, x):
    assert not expect.compare(actual, rule)[0], (actual, rule)              # a diverged loss passes nothing
    assert not expect.compare(text, f"{op} {x!r}")[0] and not expect.compare(text, f"between {-abs(x)!r} and inf")[0]


@fast(200)
@given(st.booleans(), st.sampled_from([">=", "<=", ">", "<"]), st.floats(allow_nan=False, allow_infinity=False))
def test_true_and_false_are_not_numbers(actual, op, x):
    assert not expect.compare(actual, f"{op} {x!r}")[0]
    assert not expect.compare(actual, x)[0] and not expect.compare(x, actual)[0]


finite = st.floats(min_value=-1e12, max_value=1e12, allow_nan=False)


@fast(500)
@given(finite, finite, st.floats(min_value=0, max_value=1e12))
def test_a_tolerance_holds_exactly_when_the_value_is_within_it(a, c, t):
    ok = expect.compare(a, f"~= {c!r} +- {t!r}")[0]
    off, slack = abs(Fraction(a) - Fraction(c)), Fraction(8 * math.ulp(max(abs(a), abs(c), t)))
    if off <= Fraction(t):
        assert ok, (a, c, t)
    if off > Fraction(t) + slack:
        assert not ok, (a, c, t)


@fast(400)
@given(finite, finite, finite)
def test_a_range_and_a_comparison_agree_with_arithmetic(a, lo, hi):
    lo, hi = min(lo, hi), max(lo, hi)
    assert expect.compare(a, f"between {lo!r} and {hi!r}")[0] is (lo <= a <= hi)
    for op, holds in ((">=", a >= lo), ("<", a < lo), ("==", a == lo), ("!=", a != lo)):
        assert expect.compare(a, f"{op} {lo!r}")[0] is holds


@fast(300)
@given(odd_text)
def test_check_number_is_finite_or_none(detail):
    for d in (detail, f"{detail} (wanted >= 1)"):
        n = R.check_number({"detail": d})
        assert n is None or math.isfinite(n)


# ---- reports, pages, proof ----------------------------------------------------------------------------------------

statuses = st.sampled_from(["passed", "failed", "error", "timeout", "cancelled", "odd"])


@st.composite
def reports(draw):
    t = lambda: draw(odd_text)
    steps = [{"name": t(), "kind": draw(st.sampled_from(["run", "notebook", "web"])), "status": draw(statuses),
              "minutes": draw(st.floats(0, 100)), "dir": "steps/00-x", "stdout_tail": t(),
              "error": draw(st.sampled_from([None, {"ename": t(), "evalue": t(), "line": t(), "traceback_tail": t()}])),
              "expectations": [{"check": t(), "ok": draw(st.booleans()), "detail": t()} for _ in range(draw(st.integers(0, 3)))]}
             for _ in range(draw(st.integers(0, 3)))]
    return {"run_id": t(), "plan": t(), "backend": t(), "status": draw(statuses), "started": 1700000000, "minutes": 1.5,
            "cost_usd": draw(st.sampled_from([None, 0.25])), "steps": steps, "skipped": [t()], "stopped_because": t(),
            "evidence": [{"path": t(), "bytes": 1, "sha256": t()}], "evidence_sha256": t()}


@fast(200)
@given(reports())
def test_every_report_renders_as_markdown_html_and_valid_junit(rep):
    with tempfile.TemporaryDirectory() as d:
        md, page, xml = R.render(rep), R.render_html(rep, Path(d)), R.render_junit(rep)
    for text in (md, page, xml):
        text.encode("utf-8")
    ET.fromstring(xml.encode("utf-8"))
    assert "<script>" not in page
    rows = md.split("\n## Steps\n\n", 1)[1].split("\n\n", 1)[0].splitlines()
    assert all(ln.replace("\\|", "").count("|") == 6 for ln in rows), rows


@fast(60)
@given(st.lists(st.one_of(values.map(json.dumps), st.binary(max_size=20), reports().map(json.dumps)), max_size=4))
def test_ui_builds_from_any_run_folders(contents):
    with tempfile.TemporaryDirectory() as d:
        for i, text in enumerate(contents):
            run = Path(d) / ".testbench" / "runs" / f"r{i}"
            run.mkdir(parents=True)
            (run / "state.json").write_text("{}")
            (run / "report.json").write_bytes(text if isinstance(text, bytes) else text.encode("utf-8", "surrogatepass"))
        assert ui.build(Path(d), {"project": "p", "plans": {"p": {}}}).exists()


@fast(60)
@given(st.dictionaries(st.text("abc", min_size=1, max_size=4), st.binary(max_size=30), min_size=1, max_size=4),
       st.data())
def test_verify_finds_any_changed_added_or_removed_file(files, data):
    with tempfile.TemporaryDirectory() as d:
        run = Path(d)
        for name, body in files.items():
            (run / "steps" / name).parent.mkdir(parents=True, exist_ok=True)
            (run / "steps" / name).write_bytes(body)
        recorded, total = provenance.evidence(run)
        rep = {"evidence": recorded, "evidence_sha256": total}
        assert provenance.verify(run, rep) == []
        name = data.draw(st.sampled_from(sorted(files)))
        how = data.draw(st.sampled_from(["change", "remove", "add", "edit-list"]))
        f = run / "steps" / name
        if how == "change":
            f.write_bytes(f.read_bytes() + b"!")
        elif how == "remove":
            f.unlink()
        elif how == "add":
            (run / "steps" / (name + "-new")).write_bytes(b"x")
        else:
            rep = {**rep, "evidence": [{**e, "sha256": "0" * 64} if e["path"].endswith("/" + name) else e for e in recorded]}
        assert provenance.verify(run, rep)


# ---- testbench init, prices, form fields, loops --------------------------------------------------------------------

names = joined(list("ab1 :#{}[]'\",&*!|>%@`-_.ü😀") + ["true", "null", "lint", "- ", "? ", "0x1"], 8)


@fast(40)
@given(st.lists(names, min_size=1, max_size=3, unique=True))
def test_init_writes_yaml_that_loads_for_any_notebook_name(stems):
    with tempfile.TemporaryDirectory() as d:
        root = Path(d)
        for stem in stems:
            nbformat.write(nbformat.v4.new_notebook(cells=[nbformat.v4.new_code_cell("x = 1 #@param")]),
                           str(root / f"{stem}.ipynb"))
        found = scaffold.detect(root)
        cfg = C.validate(yaml.safe_load("project: p\nplans:\n" + "".join(text for _, text, _ in found)), root)
        got = {s["notebook"] for p in cfg["plans"].values() for s in p["steps"] if s["kind"] == "notebook"}
        assert got == {p.relative_to(root).as_posix() for p in root.glob("*.ipynb")}


@fast(150)
@given(st.dictionaries(st.sampled_from(["modal", "colab", "version"]), values, max_size=3)
       | st.fixed_dictionaries({"modal": st.fixed_dictionaries({"gpu_per_s": values, "cpu_core_per_s": values}),
                                "colab": st.fixed_dictionaries({"units_per_hour": values, "usd_per_unit": values})}))
def test_a_catalog_never_lowers_a_price_never_adds_a_free_gpu_never_crashes(catalog):
    prices.cache_path().parent.mkdir(parents=True, exist_ok=True)
    prices.cache_path().write_text(json.dumps(catalog))
    cfg = C.validate({"project": "p"}, ROOT)
    for b, built_in, rate in ((modal_backend.backend, modal_backend.GPU_PER_S, 60),
                              (colab_backend.backend, colab_backend.UNITS_PER_HOUR, colab_backend.USD_PER_UNIT / 60)):
        for gpu in b.gpus:
            got = b.rate_per_minute(cfg, {"backend": b.name, "gpu": gpu})
            assert math.isfinite(got) and got > 0, (gpu, got)
            assert got >= built_in.get(gpu, 0) * rate * (1 - 1e-12)
        assert b.prices(cfg)


@fast(200)
@given(st.from_regex(r"[A-Za-z_][A-Za-z0-9_]{0,8}", fullmatch=True),
       st.one_of(st.text(max_size=12), st.integers(), st.floats(allow_nan=False, allow_infinity=False), st.booleans(),
                 st.none(), st.lists(st.integers(), max_size=3)), st.text(max_size=20))
def test_form_fields_set_the_value_the_way_the_colab_form_does(name, value, before):
    assume(name not in ("True", "False", "None") and not __import__("keyword").iskeyword(name))
    src = f"{name} = {before!r}  #@param {{type:'raw'}}"
    assert name in NB.form_fields(src)
    scope = {}
    exec(NB.set_params([src], {name: value})[0], scope)
    assert scope[name] == value


@fast(200)
@given(odd_text)
def test_form_fields_and_metric_specs_take_any_text(text):
    assert isinstance(NB.form_fields(text), dict)
    try:
        path, key = LP.parse_metric(text)
    except LP.LoopError:
        return
    assert path and key and path == path.strip() and key == key.strip()
